const safe=v=>String(v).replace(/[<>&"']/g,'');
export function portrait(c,size=100){
 const color=safe(c.color||'#756d55'), hat=c.hat||'scholar';
 const isLady=hat==='lady', isGen=hat==='general', isEmp=hat==='emperor',isSailor=hat==='sailor';
 const head=isEmp?'<path d="M29 32V15h42v17" fill="#252d2d"/><path d="M22 17h56v6H22z" fill="#b99a55"/><path d="M25 21v20m54-20v20" stroke="#d9b96a" stroke-width="2"/>':isGen?'<path d="M26 39q-1-31 24-32 24 1 25 32l-13-4H37z" fill="#475c59"/><path d="M50 9V0m-4 2h8" stroke="#ae4131" stroke-width="5"/><path d="M31 24h39" stroke="#cbb47f" stroke-width="4"/>':isLady?'<path d="M26 38q-6-26 11-29 3-15 17-6 19-5 22 17l-3 21z" fill="#252d2d"/><path d="M31 21q20-11 39 1" fill="none" stroke="#e0b555" stroke-width="4"/><circle cx="50" cy="16" r="4" fill="#b54533"/>':isSailor?'<path d="M25 35L27 15q23-13 45 0l4 20-18-10-26 8z" fill="#eee1c1"/><path d="M27 17l42 5" stroke="#b09358" stroke-width="4"/>':'<path d="M27 34V13q23-11 46 0v22l-9-4-29 2z" fill="#263d39"/><path d="M26 18l-19 4v10l20-4m47-10 18 4v10l-18-4" fill="#263d39"/>';
 const beard=(!isLady&&!isSailor)?'<path d="M39 58q12 11 23 0-1 19-12 23-9-5-11-23" fill="#343b34"/><path d="M39 57q4-5 11 0 7-5 13 0" fill="none" stroke="#343b34" stroke-width="2"/>':'';
 return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${safe(c.name)}的原创卡通像" viewBox="0 0 100 112" width="${size}" height="${size*1.12}"><defs><clipPath id="p-${safe(c.id)}"><rect width="100" height="112" rx="50"/></clipPath></defs><g clip-path="url(#p-${safe(c.id)})"><circle cx="50" cy="53" r="48" fill="${color}" opacity=".13"/><path d="M8 112q-1-41 31-44h23q32 4 32 44" fill="${color}"/><path d="M32 72l18 36 18-36-14 8-4 15-5-16z" fill="#ede2c5"/><path d="M43 60v15l8 9 8-9V60" fill="#d8a97c"/><ellipse cx="50" cy="43" rx="22" ry="28" fill="#e6ba8d"/><ellipse cx="28" cy="45" rx="4" ry="7" fill="#dda779"/><ellipse cx="72" cy="45" rx="4" ry="7" fill="#dda779"/>${head}<path d="M36 40l9-2m11 0 9 2" stroke="#393e33" stroke-width="2" stroke-linecap="round"/><path d="M39 45h2m19 0h2" stroke="#272c29" stroke-width="3" stroke-linecap="round"/><path d="M51 43l-3 9h5m-8 8q6 3 12-1" stroke="#af784f" stroke-width="1.5" fill="none"/>${beard}${isLady?'<circle cx="29" cy="53" r="3" fill="#d3ad56"/><circle cx="72" cy="53" r="3" fill="#d3ad56"/>':''}<path d="M22 96l-5 16m60-16 6 16" stroke="#fff" opacity=".18" stroke-width="2"/></g></svg>`;
}
